def find_sample() -> str:
    """A wildlife val image if the dataset is present, else a stock Ultralytics URL."""
    import ultralytics
    # african-wildlife auto-downloads under <ultralytics-parent>/datasets/
    root = Path(ultralytics.__file__).resolve().parents[1]
    for base in (root, Path.home()):
        val = base / "datasets" / "african-wildlife" / "images" / "val"
        if val.is_dir():
            imgs = sorted(val.glob("*.jpg"))
            if imgs:
                return str(imgs[0])
    return "https://ultralytics.com/images/zidane.jpg"

